/*
 * VN06 — preset importe de Lightroom.
 *
 * GENERE PAR `scripts/import-lightroom-preset.mjs`. Ne pas editer a la main:
 * relancer l'import si le preset change dans Lightroom.
 *
 * La couleur vient d'une Hald CLUT passee dans Lightroom: ce n'est pas une
 * approximation des calculs d'Adobe, c'est leur resultat mesure sur toute la
 * grille RVB (ecart moyen a l'identite: 23.0/255, max 168/255).
 *
 * Reglages lus dans le .xmp ou releves dans Lightroom:
 *   - blancs -50
 *   - noirs -53
 *   - texture -15
 *   - voile +14
 *   - grain +22
 *   - taille du grain +17
 *   - cassure du grain +50
 *   - saturation -7
 *   - mélangeur — red T+13/S-6/L-25, orange T-5/S-1/L-10, yellow T+16/S-23, green T+37/S-48, aqua T+21/S-7, blue T+15/S-9/L-12, purple T+27/S-3, magenta T+25/S-20
 *   - courbe maître 5 points
 *   - courbes RVB par canal
 * Reglages hors LUT effectivement importes:
 *   - texture: -15
 *   - grain: 22
 *   - grainSize: 17
 *   - grainRoughness: 50
 *   - dehaze: 14
 *   - presetSpatialBeforeLut: true
 *   - presetTextureEdgeAware: true
 *
 * Source Hald : hald-clut-neutre-niveau8-bloc4.png (niveau 8, cube 64)
 * Importe le  : 2026-08-31
 */

import { lutFromBase64 } from '../haldClut.js';

const LUT_BASE64 = '';

let cached = null;

export const preset = {
    id: 'vn06',
    label: "VN06",
    collection: {"id":"vintage","label":"Vintage"},
    hint: "Preset importé de Lightroom",
    description: "Capturé depuis Lightroom par table de conversion complète. Réglages : blancs -50 · noirs -53 · texture -15 · voile +14 · grain +22 · taille du grain +17 · cassure du grain +50 · saturation -7 · mélangeur — red T+13/S-6/L-25, orange T-5/S-1/L-10, yellow T+16/S-23, green T+37/S-48, aqua T+21/S-7, blue T+15/S-9/L-12, purple T+27/S-3, magenta T+25/S-20 · courbe maître 5 points · courbes RVB par canal.",
    bestFor: "à définir après essai sur tes photos",
    avoidFor: "photos déjà fortement filtrées",
    recommendedIntensity: 100,
    /* Reglages que la table ne peut pas porter (ils dependent des pixels
       voisins ou de la position dans l'image), lus dans le .xmp. */
    spatialFilters: {"texture":-15,"grain":22,"grainSize":17,"grainRoughness":50,"dehaze":14,"presetSpatialBeforeLut":true,"presetTextureEdgeAware":true},
    /* La table elle-meme, decodee au premier usage. */
    getLut() {
        if (!cached) cached = lutFromBase64(LUT_BASE64);
        return cached;
    },
};

export default preset;
